def shared_ancestor(root: "TreeNode | None", p: "TreeNode", q: "TreeNode") -> "TreeNode | None":
    if root is None or root is p or root is q:
        return root                       # nothing here, or a target: report it upward
    left = shared_ancestor(root.left, p, q)
    right = shared_ancestor(root.right, p, q)
    if left and right:
        return root                       # p and q came up from different sides: the split
    return left or right                  # pass up whatever one side found


