def contains(node: "TreeNode | None", target: "TreeNode") -> bool:
    if node is None:
        return False
    return node is target or contains(node.left, target) or contains(node.right, target)


def shared_ancestor(root: "TreeNode | None", p: "TreeNode", q: "TreeNode") -> "TreeNode | None":
    # Walk down while one child's subtree still holds both targets: a full search per step.
    for child in (root.left, root.right):
        if contains(child, p) and contains(child, q):
            return shared_ancestor(child, p, q)
    return root


